discrete TidalEnergyCaptureSystem
port:
    event input real WaterLevelChangeSignal;  // Water level change signalS1
    event output real SignalToEnergyConversion;  // SignalS1
state:
    initial state InitialState
        when entry() then
            statehold(0);
        end;
        when receive(WaterLevelChangeSignal) then
            transition(WorkingState);
        end;
    end;

    state WorkingState
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(InitialState);
        end;
    end;
end;
end;

discrete EnergyConversionSystem
port:
    event input real ActivationCommand;
    event input real PowerOutput;
    event output real FaultSignal;
state:
    initial state PreparationState
        when entry() then
            statehold(0);
        end;
        when receive(ActivationCommand) then
            transition(GenerationState);
        end;
    end;

    state GenerationState
        when entry() then
            statehold(0);
        end;
        when receive(PowerOutput) then
            transition(FaultHandlingState);
        end;
        when timeover() then
            transition(PreparationState);
        end;
    end;

    state FaultHandlingState
        when entry() then
            statehold(0);
        end;
        when receive(ActivationCommand) then
            transition(GenerationState);
        end;
        when timeover() then
            transition(PreparationState);
        end;
    end;
end;
end;

discrete PowerManagementSystem
port:
    event input real ExternalGridDemand;
    event input real InternalStorageLevel;
    event input real ExtremeWeatherCondition;
    event output real RegulationRequest;
state:
    initial state MonitoringState
        when entry() then
            statehold(0);
        end;
        when receive(ExternalGridDemand) then
            transition(RegulationState);
        end;
        when receive(InternalStorageLevel) then
            transition(RegulationState);
        end;
        when timeover() then
            transition(MonitoringState);
        end;
    end;

    state RegulationState
        when entry() then
            statehold(0);
        end;
        when receive(ExtremeWeatherCondition) then
            transition(EmergencyResponseState);
        end;
        when timeover() then
            transition(MonitoringState);
        end;
    end;

    state EmergencyResponseState
        when entry() then
            statehold(0);
        end;
        when receive(ExtremeWeatherCondition) then
            transition(MonitoringState);
        end;
        when timeover() then
            transition(MonitoringState);
        end;
    end;
end;
end;

couple TidalEnergySystem
import architectureModels.TidalEnergyCaptureSystem as Tidal;
import architectureModels.EnergyConversionSystem as Energy;
import architectureModels.PowerManagementSystem as Power;

part:
    Tidal tidalInstance;
    Energy energyInstance;
    Power powerInstance;

connection:
    connect(tidalInstance.EnergyOutput, energyInstance.TidalEnergyInput);
    connect(energyInstance.ConvertedPowerOutput, powerInstance.EnergyInput);
    connect(powerInstance.PowerAdjustmentOutput, energyInstance.PowerAdjustmentInput);
end;
